INSERT INTO source_documents (id, project_id, code, title, publisher, url, retrieved_at, sha256, local_path, page_ref, license_status, license_note, license_checked_at, is_latest_note, meta_json) VALUES ('5a1e0000-0000-4000-8000-000000000502', '5a1e0000-0000-4000-8000-000000000001', 'S2', '中壢運動公園區段徵收範圍圖（JPG）', '桃園市政府地政局', 'https://ws.tycg.gov.tw/001/Upload/62/relpic/9911/705/0.jpg', '2026-10-22T08:07+08:00', '3782821e23c3a6c9b98686aca90011325daf3c7e0f893e810f33dd7f0e6479ff', 'sources/raw/S2_zlsp_range_map.jpg', NULL, 'internal_only', '授權條款未核對；公開分享前須確認', '2026-10-22', '未知；官方頁面目前連結此圖', '{"id":"S2","title":"中壢運動公園區段徵收範圍圖（JPG）","publisher":"桃園市政府地政局","url":"https://ws.tycg.gov.tw/001/Upload/62/relpic/9911/705/0.jpg","retrieved_at":"2026-10-22T08:07+08:00","local_file":"sources/raw/S2_zlsp_range_map.jpg","sha256":"3782821e23c3a6c9b98686aca90011325daf3c7e0f893e810f33dd7f0e6479ff","pixel_size":[1024,814],"version_date":"圖面未標日期","license_status":"internal_only","license_note":"授權條款未核對；公開分享前須確認","usage":"沙盤主底圖（圖面座標模式）。紅色虛線為範圍界線；圖面有比例尺與指北針。","scale_measurement":{"method":"比例尺黑白格像素量測：0/40/80/120/160m 刻度分別位於 x=943,961,979,997,1015（y≈95）","meters_per_pixel":2.2222,"uncertainty":"±1px／18px 每格 ≈ ±5.6%","sanity_check":"依紅線粗描 25 點多邊形計算約 76.6 公頃；官方 74.2（都計）／72.97（區徵）公頃，差 3–5%，在比例尺與描圖誤差內"},"is_latest":"未知；官方頁面目前連結此圖"}');
